export function debounce<T extends (...args: any[]) => any>(fn: T, delay: number): T {
  let timeout: any;
  return ((...args: any[]) => {
    clearTimeout(timeout);
    timeout = setTimeout(() => fn(...args), delay);
  }) as T;
}

